func (s *Server) streamAI(w http.ResponseWriter, r *http.Request) {
	u := userFromContext(r.Context())
	var in struct {
		Prompt          string `json:"prompt"`
		PersonID        string `json:"person_id"`
		MaxOutputTokens int    `json:"max_output_tokens"`
	}
	if !decodeJSON(w, r, &in) {
		return
	}
	in.Prompt = strings.TrimSpace(in.Prompt)
	if in.Prompt == "" || len([]rune(in.Prompt)) > 32000 {
		writeError(w, 400, "validation_error", "질문은 1~32,000자로 입력해 주세요.")
		return
	}
	// relationshipContext는 이 값을 uuid 컬럼인 p.id와 맞대므로, 모양이 어긋난
	// 문자열은 postgres의 22P02를 거쳐 500이 된다. 잘못 보낸 요청이니 400으로 돌려보낸다.
	// 빈 값은 사람을 고르지 않은 전체 관계 요약 경로라 그대로 둔다.
	//
	// 이 가드를 설정 조회보다 앞에 두었다. 그 대가로 AI가 비활성이면서 동시에
	// person_id가 깨진 요청의 응답이 503 ai_disabled에서 400으로 바뀐다 —
	// 입력 검증을 DB 앞에서 끝내는 이 저장소의 관례(validateInteractionInput,
	// data.go의 id 가드)를 따른 의도된 변경이고, 호출자가 먼저 고쳐야 할 것은
	// 자기 요청 쪽이다.
	if in.PersonID != "" && !looksLikeUUID(in.PersonID) {
		writeError(w, 400, "validation_error", "사람을 확인해 주세요.")
		return
	}
	var settings AISettings
	var secret string
	if err := s.readSetting(r.Context(), "ai", "provider", &settings, &secret); err != nil {
		internalError(w, r, err)
		return
	}
	settings.APIKey = secret
	if !settings.Enabled {
		writeError(w, 503, "ai_disabled", "관리자 설정에서 AI를 먼저 활성화해 주세요.")
		return
	}
	limit := settings.MaxOutputTokens
	if in.MaxOutputTokens > 0 && in.MaxOutputTokens < limit {
		limit = in.MaxOutputTokens
	}
	if limit > 262144 {
		limit = 262144
	}
	contextText, err := s.relationshipContext(r.Context(), u.ID, in.PersonID)
	if err != nil {
		if errors.Is(err, errAIRelationshipNotFound) {
			writeError(w, 404, "not_found", "사람을 찾을 수 없습니다.")
			return
		}
		internalError(w, r, err)
		return
	}
	w.Header().Set("Content-Type", "text/event-stream; charset=utf-8")
	w.Header().Set("Cache-Control", "no-cache, no-transform")
	w.Header().Set("Connection", "keep-alive")
	w.Header().Set("X-Accel-Buffering", "no")
	flusher, ok := w.(http.Flusher)
	if !ok {
		writeError(w, 500, "stream_unsupported", "스트리밍을 지원하지 않는 연결입니다.")
		return
	}
	sendSSE(w, "meta", map[string]any{"model": settings.Model, "max_output_tokens": limit})
	flusher.Flush()
	if err := s.proxyAIStream(r.Context(), w, flusher, settings, in.Prompt, contextText, limit); err != nil {
		// 사용자에게는 원인을 말하지 않는다 — 제공자 응답 본문에 무엇이 들었는지
		// 알 수 없어 그대로 흘리면 안 된다. 그래서 고정 문구를 먼저 보내 응답
		// 바이트열을 예전과 똑같이 유지하고, 원인은 운영자만 보는 로그로 돌린다.
		sendSSE(w, "error", map[string]string{"message": "AI 응답을 완료하지 못했습니다."})
		flusher.Flush()
		// 클라이언트가 탭을 닫으면 context canceled 가 올라온다. 정상적인 이탈이라
		// ERROR 로 남기면 이탈마다 오탐이 쌓인다 — internalError(respond.go)와
		// 같은 판정을 쓴다.
		if errors.Is(err, r.Context().Err()) {
			return
		}
		// 이 한 줄이 없으면 제공자 401/429/500·잘못된 엔드포인트·타임아웃이 전부
		// 위의 같은 한 문장으로만 보여, 운영자가 "AI가 안 된다"는 신고를 받아도
		// 원인을 알 방법이 없다. 감사(s.audit)에는 넘기지 않는다 — 감사 출력이
		// 제공자 응답 원문을 다시 내보내게 된다.
		slog.Error("AI 스트림이 중간에 끊겼습니다", "user", u.ID, "model", settings.Model, "error", safeAIError(err))
		return
	}
	sendSSE(w, "done", map[string]bool{"ok": true})
	flusher.Flush()
	s.audit(r.Context(), u.ID, "ai.invoke", "ai", "", r.RemoteAddr, map[string]any{"model": settings.Model, "person_context": in.PersonID != "", "stream": true})
}

